import java.util.*;

public class HashIndex {
    // Same spreading HashMap uses (Java 8+): mix high bits into low bits.
    static int spread(Object key) {
        int h;
        return (key == null) ? 0 : (h = key.hashCode()) ^ (h >>> 16);
    }
    static int bucket(Object key, int capacity) { return (capacity - 1) & spread(key); }

    public static void main(String[] args) {
        int capacity = 16;                       // default table size
        for (String k : List.of("apple", "banana", "cherry", "Aa", "BB")) {
            System.out.printf("%-7s hashCode=%-11d bucket=%d%n", k, k.hashCode(), bucket(k, capacity));
        }
        // "Aa" and "BB" have the same hashCode (2112): a real collision, same bucket.
        Map<String, Integer> m = new HashMap<>();
        m.put("Aa", 1); m.put("BB", 2); m.put(null, 0); // one null key is allowed (bucket 0)
        System.out.println(m.get("Aa") + " " + m.get("BB") + " " + m.get(null));
        // Threshold = capacity * loadFactor = 16 * 0.75 = 12: the 13th put doubles the table to 32.
    }
}

import java.util.*;

public class BrokenKey {
    // equals() overridden but hashCode() NOT: breaks the contract.
    static final class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
        @Override public boolean equals(Object o) {
            return o instanceof Point p && p.x == x && p.y == y;
        }
    }
    // Fixed version: equal objects must have equal hash codes.
    record FixedPoint(int x, int y) { }

    public static void main(String[] args) {
        Map<Point, String> broken = new HashMap<>();
        broken.put(new Point(1, 2), "A");
        System.out.println("broken get  -> " + broken.get(new Point(1, 2)));   // almost always null

        Map<FixedPoint, String> fixed = new HashMap<>();
        fixed.put(new FixedPoint(1, 2), "A");
        System.out.println("record get  -> " + fixed.get(new FixedPoint(1, 2))); // A

        // Mutable key pitfall: mutate after insert and the entry is "lost".
        List<Integer> key = new ArrayList<>(List.of(1));
        Map<List<Integer>, String> m = new HashMap<>();
        m.put(key, "v");
        key.add(2);                                   // hashCode changes
        System.out.println("mutated key -> " + m.get(key) + ", size=" + m.size()); // null, size=1
    }
}

import java.util.*;
import java.util.concurrent.*;

public class FailFastAndThreads {
    public static void main(String[] args) throws Exception {
        Map<String, Integer> stock = new HashMap<>(Map.of("pen", 0, "book", 3, "bag", 0));
        try {
            for (String k : stock.keySet()) if (stock.get(k) == 0) stock.remove(k); // structural change mid-iteration
        } catch (ConcurrentModificationException e) {
            System.out.println("fail-fast: " + e.getClass().getSimpleName());
        }
        stock.values().removeIf(v -> v == 0);       // correct way
        System.out.println("after removeIf: " + stock);

        // Lost updates: HashMap is not thread-safe. ConcurrentHashMap.merge is atomic per key.
        System.out.println("HashMap total = " + count(new HashMap<>()) + " (expected 80000; usually less, may even throw)");
        System.out.println("ConcurrentHashMap total = " + count(new ConcurrentHashMap<>()));
    }

    static int count(Map<Integer, Integer> map) throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(8);
        for (int t = 0; t < 8; t++) pool.submit(() -> {
            for (int i = 0; i < 10_000; i++) map.merge(i % 100, 1, Integer::sum);
        });
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
        return map.values().stream().mapToInt(Integer::intValue).sum();
    }
}
